def gen(rng):
    def fmt(g):
        return str(len(g)) + '\n' + '\n'.join(' '.join(map(str, r)) for r in g)
    def rnd(n, lo, hi):
        return [[rng.randint(lo, hi) for _ in range(n)] for _ in range(n)]
    tests = [
        fmt([[5]]),
        fmt([[-7]]),
        fmt([[1, 2, 3], [4, 5, 6], [7, 8, 9]]),
        fmt([[1, -2], [3, 4]]),
        fmt([[0, 0], [0, 0]]),
        fmt([[1000, 1000], [1000, 1000]]),
        fmt([[-1000] * 3, [-1000] * 3, [-1000] * 3]),
    ]
    for n in (1, 2, 3, 4, 5, 6, 7, 8):
        for _ in range(3):
            tests.append(fmt(rnd(n, -20, 20)))
    tests.append(fmt(rnd(100, -1000, 1000)))
    tests.append(fmt(rnd(499, -1000, 1000)))
    tests.append(fmt(rnd(500, -1000, 1000)))
    tests.append(fmt([[1000] * 500 for _ in range(500)]))
    return tests
